<?phprequire_once('common_api_header.php');require_once('../admin/controllers/common_controllers.php');require_once('../admin/booking/controller/booking_controller.php');$data_raw = file_get_contents('php://input');$data = json_decode($data_raw,true);$response = array();function getAllCorporateTickets($conn,$data){	$BranchID = -1;	$filter_limit = "";	if(isset($data['start_counter']))	{		$start_counter = $data['start_counter'];		$no_of_records = $data['no_of_records'];		$filter_limit = " ORDER BY ID DESC LIMIT $start_counter,$no_of_records ";	}	if(isset($data['BranchID']))	{		$BranchID = $data['BranchID'];	}	$CorporateID = $data['CorporateID'];	$response = array();	$response['data'] = array();	if($BranchID == -1)	{		$where = " where CorporateID = $CorporateID and (Status='Completed' OR Status='Closed')";	}	else	{		$where = " where CorporateID = $CorporateID and BranchID = $BranchID and (Status='Completed' OR Status='Closed')";	}	$where = $where.$filter_limit;	$response['data'] = _getTableRecords($conn,'corporate_tickets', $where);	$response['error'] = false;	$response['message'] = "Tickets fetched";	return $response;}if(isset($data['CorporateID'])){	$conn = _connectodb();	$response = getAllCorporateTickets($conn,$data);}else{	$response["error"] = true;	$response["message"] = "Missing User Fields";}echo json_encode($response);?>